import { parseAddr, toAddr } from "./addr.mjs";

const REF = /^\$?[A-Za-z]{1,3}\$?[1-9]\d*$/;
const NUM = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;
const TOKEN = /\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|"((?:[^"]|"")*)"|([A-Za-z_$][A-Za-z0-9_.$]*)|(<>|<=|>=|[=<>&+\-*\/^(),:]))/y;

function tokenize(text) {
  const out = [];
  let pos = 0;
  while (true) {
    const rest = /\s*/y;
    rest.lastIndex = pos;
    rest.exec(text);
    pos = rest.lastIndex;
    if (pos >= text.length) break;
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(text);
    if (!m) throw new SyntaxError(`unexpected character at ${pos}: ${text[pos]}`);
    pos = TOKEN.lastIndex;
    if (m[1] !== undefined) out.push({ t: "num", v: Number(m[1]) });
    else if (m[2] !== undefined) out.push({ t: "str", v: m[2].replace(/""/g, '"') });
    else if (m[3] !== undefined) out.push({ t: "id", v: m[3] });
    else out.push({ t: "op", v: m[4] });
  }
  return out;
}

const normAddr = (s) => s.replace(/\$/g, "").toUpperCase();

/** Parse formula text (without the leading `=`) into an AST. Throws SyntaxError on bad syntax. */
export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const isOp = (v) => toks[i] && toks[i].t === "op" && toks[i].v === v;
  const expect = (v) => {
    if (!isOp(v)) throw new SyntaxError(`expected ${v}`);
    i++;
  };
  const levels = [["=", "<>", "<", ">", "<=", ">="], ["&"], ["+", "-"], ["*", "/"], ["^"]];

  function binary(level) {
    if (level === levels.length) return unary();
    let left = binary(level + 1);
    while (toks[i] && toks[i].t === "op" && levels[level].includes(toks[i].v)) {
      const op = toks[i++].v;
      left = { type: "bin", op, left, right: binary(level + 1) };
    }
    return left;
  }
  function unary() {
    if (isOp("-") || isOp("+")) {
      const op = toks[i++].v;
      return { type: "un", op, arg: unary() };
    }
    return primary();
  }
  function primary() {
    const tok = toks[i++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    if (tok.t === "num") return { type: "num", value: tok.v };
    if (tok.t === "str") return { type: "str", value: tok.v };
    if (tok.t === "op") {
      if (tok.v !== "(") throw new SyntaxError(`unexpected ${tok.v}`);
      const e = binary(0);
      expect(")");
      return e;
    }
    if (isOp("(")) {
      i++;
      const args = [];
      if (!isOp(")")) {
        do args.push(binary(0)); while (isOp(",") && i++);
      }
      expect(")");
      return { type: "call", name: tok.v.toUpperCase(), args };
    }
    const up = tok.v.toUpperCase();
    if (up === "TRUE" || up === "FALSE") return { type: "bool", value: up === "TRUE" };
    if (!REF.test(tok.v)) throw new SyntaxError(`bad name: ${tok.v}`);
    const a = normAddr(tok.v);
    if (isOp(":")) {
      i++;
      const t2 = toks[i++];
      if (!t2 || t2.t !== "id" || !REF.test(t2.v)) throw new SyntaxError("bad range");
      return { type: "range", from: a, to: normAddr(t2.v) };
    }
    return { type: "ref", addr: a };
  }

  const ast = binary(0);
  if (i < toks.length) throw new SyntaxError(`unexpected ${toks[i].v}`);
  return ast;
}

function rangeAddrs(from, to) {
  const a = parseAddr(from), b = parseAddr(to);
  const out = [];
  for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) out.push(toAddr(c, r));
  return out;
}

/** Normalized cell addresses the formula reads, ranges expanded row by row, each once, in order of first appearance. */
export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    if (n.type === "ref") seen.add(n.addr);
    else if (n.type === "range") rangeAddrs(n.from, n.to).forEach((a) => seen.add(a));
    else if (n.type === "bin") (walk(n.left), walk(n.right));
    else if (n.type === "un") walk(n.arg);
    else if (n.type === "call") n.args.forEach(walk);
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null || v === undefined) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "boolean") return v ? 1 : 0;
  const t = v.trim();
  return NUM.test(t) ? Number(t) : "#VALUE!";
}

function toText(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null || v === undefined) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  return u === "TRUE" ? true : u === "FALSE" ? false : "#VALUE!";
}

const typeRank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null || a === undefined) a = b === null || b === undefined ? 0 : typeof b === "string" ? "" : typeof b === "boolean" ? false : 0;
  if (b === null || b === undefined) b = typeof a === "string" ? "" : typeof a === "boolean" ? false : 0;
  const ra = typeRank(a), rb = typeRank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) (a = a.toLowerCase(), b = b.toLowerCase());
  return a < b ? -1 : a > b ? 1 : 0;
}

function round(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  let r;
  const s = String(abs);
  if (!s.includes("e") && Math.abs(d) < 300) r = Number(Math.round(Number(`${s}e${d}`)) + `e${-d}`);
  else r = Math.round(abs * 10 ** d) / 10 ** d;
  return x < 0 ? -r : r;
}

const fin = (n) => (Number.isFinite(n) ? n : "#NUM!");

/** Value of the formula; `lookup(addr)` returns a cell's value (null if empty). */
export function evaluate(ast, lookup) {
  const get = (a) => lookup(a) ?? null;

  function ev(n) {
    switch (n.type) {
      case "num": case "str": case "bool": return n.value;
      case "ref": return get(n.addr);
      case "range": return "#VALUE!";
      case "un": {
        const x = toNum(ev(n.arg));
        if (typeof x === "string") return x;
        return n.op === "-" ? fin(-x) : x;
      }
      case "bin": return bin(n);
      case "call": return call(n);
    }
  }

  function bin(n) {
    const l = ev(n.left);
    if (isErr(l)) return l;
    const r = ev(n.right);
    if (isErr(r)) return r;
    const op = n.op;
    if (op === "&") return toText(l) + toText(r);
    if (["=", "<>", "<", ">", "<=", ">="].includes(op)) {
      const c = compare(l, r);
      return { "=": c === 0, "<>": c !== 0, "<": c < 0, ">": c > 0, "<=": c <= 0, ">=": c >= 0 }[op];
    }
    const x = toNum(l);
    if (typeof x === "string") return x;
    const y = toNum(r);
    if (typeof y === "string") return y;
    switch (op) {
      case "+": return fin(x + y);
      case "-": return fin(x - y);
      case "*": return fin(x * y);
      case "/": return y === 0 ? "#DIV/0!" : fin(x / y);
      case "^": return fin(x ** y);
    }
  }

  // Values of an argument: a range yields its cells, anything else a single direct value.
  const cells = (a) => rangeAddrs(a.from, a.to).map(get);

  function numbers(args, isCount) {
    const nums = [];
    for (const a of args) {
      if (a.type === "range") {
        for (const v of cells(a)) {
          if (isErr(v)) { if (!isCount) return v; }
          else if (typeof v === "number") nums.push(v);
        }
      } else if (isCount) {
        const v = ev(a);
        if (typeof v === "number") nums.push(v);
      } else {
        const x = toNum(ev(a));
        if (typeof x === "string") return x;
        nums.push(x);
      }
    }
    return nums;
  }

  function logic(args, isAnd) {
    let acc = isAnd;
    for (const a of args) {
      let vals;
      if (a.type === "range") {
        vals = [];
        for (const v of cells(a)) {
          if (isErr(v)) return v;
          if (typeof v === "number" || typeof v === "boolean") vals.push(toBool(v));
        }
      } else {
        const b = toBool(ev(a));
        if (typeof b === "string") return b;
        vals = [b];
      }
      for (const b of vals) acc = isAnd ? acc && b : acc || b;
    }
    return acc;
  }

  function call(n) {
    const { name, args } = n;
    const count = args.length;
    const arity = (min, max) => count >= min && count <= max;
    const bad = "#VALUE!";
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": case "COUNT": {
        const nums = numbers(args, name === "COUNT");
        if (typeof nums === "string") return nums;
        if (name === "COUNT") return nums.length;
        if (name === "SUM") return fin(nums.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") return nums.length ? fin(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return name === "MIN" ? Math.min(...nums) : Math.max(...nums);
      }
      case "IF": {
        if (!arity(2, 3)) return bad;
        const c = toBool(ev(args[0]));
        if (typeof c === "string") return c;
        if (c) return ev(args[1]);
        return count === 3 ? ev(args[2]) : false;
      }
      case "AND": case "OR":
        return count >= 1 ? logic(args, name === "AND") : bad;
      case "NOT": {
        if (count !== 1) return bad;
        const b = toBool(ev(args[0]));
        return typeof b === "string" ? b : !b;
      }
      case "ROUND": {
        if (count !== 2) return bad;
        const x = toNum(ev(args[0]));
        if (typeof x === "string") return x;
        const d = toNum(ev(args[1]));
        if (typeof d === "string") return d;
        return fin(round(x, d));
      }
      case "ABS": {
        if (count !== 1) return bad;
        const x = toNum(ev(args[0]));
        return typeof x === "string" ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (count !== 1) return bad;
        const v = ev(args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let out = "";
        for (const a of args) {
          for (const v of a.type === "range" ? cells(a) : [ev(a)]) {
            if (isErr(v)) return v;
            out += toText(v);
          }
        }
        return out;
      }
      default: return "#NAME?";
    }
  }

  return ev(ast);
}
