import assert from "node:assert/strict";
import { parseFormula, refsOf, evaluate } from "../src/formula.mjs";

const run = (t, cells = {}) => evaluate(parseFormula(t), (a) => cells[a] ?? null);

test("precedence and arithmetic", () => {
  assert.equal(run("-2^2"), 4);
  assert.equal(run("2^3^2"), 64);
  assert.equal(run('1+"2"&"x"'), "3x");
  assert.equal(run("1/0"), "#DIV/0!");
  assert.equal(run("A1:B2+1"), "#VALUE!");
  assert.equal(run('"a"<TRUE'), true);
});

