// Subset of spreadsheet number formats.

function splitSections(pattern) {
  const out = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (quoted) {
      cur += c;
      if (c === '"') quoted = false;
    } else if (c === '"') {
      quoted = true;
      cur += c;
    } else if (c === "\\") {
      cur += c + (pattern[i + 1] ?? "");
      i++;
    } else if (c === ";") {
      out.push(cur);
      cur = "";
    } else cur += c;
  }
  out.push(cur);
  return out;
}

function tokenize(section) {
  const toks = [];
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      const end = section.indexOf('"', i + 1);
      const stop = end < 0 ? section.length : end;
      toks.push({ lit: section.slice(i + 1, stop) });
      i = stop;
    } else if (c === "\\") {
      if (i + 1 < section.length) toks.push({ lit: section[i + 1] });
      i++;
    } else if ((c === "E" || c === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      toks.push({ exp: section[i + 1] });
      i++;
    } else if (c === "0" || c === "#" || c === "," || c === ".") {
      toks.push({ num: c });
    } else if (c === "%") {
      toks.push({ pct: true });
    } else toks.push({ lit: c });
  }
  return toks;
}

// Decimal digits of a non-negative number as JS prints it, shifted by `shift` places.
function digitParts(abs, shift) {
  const s = String(abs);
  const [mant, e = "0"] = s.toLowerCase().split("e");
  const dot = mant.indexOf(".");
  const digits = mant.replace(".", "");
  const p = (dot < 0 ? mant.length : dot) + Number(e) + shift;
  if (p <= 0) return { int: "0", frac: "0".repeat(-p) + digits };
  if (p >= digits.length) return { int: digits + "0".repeat(p - digits.length), frac: "" };
  return { int: digits.slice(0, p), frac: digits.slice(p) };
}

function increment(str) {
  const a = str.split("");
  let i = a.length - 1;
  while (i >= 0 && a[i] === "9") a[i--] = "0";
  if (i < 0) return "1" + a.join("");
  a[i] = String(Number(a[i]) + 1);
  return a.join("");
}

// Round half away from zero to d decimals.
function roundParts({ int, frac }, d) {
  if (frac.length <= d) return { int, frac: frac.padEnd(d, "0") };
  const up = frac[d] >= "5";
  let all = int + frac.slice(0, d);
  if (up) all = increment(all);
  return { int: all.slice(0, all.length - d), frac: all.slice(all.length - d) };
}

function group(s) {
  return s.replace(/\B(?=(\d{3})+$)/g, ",");
}

function render(toks, abs, negSign) {
  const hasPct = toks.some((t) => t.pct);
  const shift = hasPct ? 2 : 0;
  const expTok = toks.find((t) => t.exp);
  const nums = toks.filter((t) => t.num).map((t) => t.num);
  const dotAt = nums.indexOf(".");
  const intPat = dotAt < 0 ? nums : nums.slice(0, dotAt);
  const fracPat = dotAt < 0 ? [] : nums.slice(dotAt + 1).filter((c) => c !== ",");
  const zeros = intPat.filter((c) => c === "0").length;
  const first = intPat.findIndex((c) => c !== ",");
  const last = intPat.length - 1 - [...intPat].reverse().findIndex((c) => c !== ",");
  const grouped = intPat.slice(first, last + 1).includes(",");
  const d = fracPat.length;
  const minFrac = fracPat.lastIndexOf("0") + 1;

  let parts = digitParts(abs, shift);
  let expStr = "";
  let intStr, fracStr;
  if (expTok) {
    const digits = (parts.int + parts.frac).replace(/^0+/, "");
    let e = 0;
    let m;
    if (digits === "") m = { int: "0", frac: "" };
    else {
      e = parts.int.replace(/^0+/, "").length - 1;
      if (parts.int.replace(/^0+/, "") === "") e = -(parts.frac.length - parts.frac.replace(/^0+/, "").length) - 1;
      m = { int: digits[0], frac: digits.slice(1) };
    }
    m = roundParts(m, d);
    if (m.int.length > 1) {
      m = { int: "1", frac: "0".repeat(d) };
      e++;
    }
    intStr = m.int;
    fracStr = m.frac;
    const ez = toks.filter((t) => t.num === "0" && toks.indexOf(t) > toks.indexOf(expTok)).length;
    const sign = e < 0 ? "-" : expTok.exp === "+" ? "+" : "";
    expStr = "E" + sign + String(Math.abs(e)).padStart(ez, "0");
  } else {
    const r = roundParts(parts, d);
    intStr = r.int.replace(/^0+/, "");
    fracStr = r.frac;
    while (fracStr.length > minFrac && fracStr.endsWith("0")) fracStr = fracStr.slice(0, -1);
    intStr = intStr.padStart(zeros, "0");
    if (grouped) intStr = group(intStr);
  }
  const isZero = !/[1-9]/.test(intStr + fracStr);
  const numText = intStr + (dotAt >= 0 ? "." : "") + fracStr + expStr;

  let out = negSign && !isZero ? "-" : "";
  let placed = false;
  let afterExp = false;
  for (const t of toks) {
    if (t.exp) {
      afterExp = true;
      continue;
    }
    if (t.num) {
      if (afterExp) continue;
      if (!placed) {
        out += numText;
        placed = true;
      }
    } else if (t.pct) out += "%";
    else out += t.lit;
  }
  return out;
}

export function formatNumber(value, pattern) {
  if (typeof value !== "number") {
    if (value === null || value === undefined) return "";
    if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
    return String(value);
  }
  if (pattern.trim().toLowerCase() === "general" || !Number.isFinite(value)) return String(value);
  const secs = splitSections(pattern);
  const neg = value < 0;
  let idx = 0;
  let sign = neg;
  if (secs.length >= 2 && neg) {
    idx = 1;
    sign = false;
  } else if (secs.length >= 3 && value === 0) idx = 2;
  return render(tokenize(secs[idx]), Math.abs(value), sign);
}
