// Inserting and deleting rows and columns, rewriting formula references to follow the moved cells.
import { parseAddr, toAddr, colName, colIndex } from "./addr.mjs";

const REF = String.raw`\$?[A-Za-z]+\$?\d+`;
const RE = new RegExp(String.raw`(?<![A-Za-z0-9_.])(${REF})(?::(${REF}))?(?![A-Za-z0-9_.(])`, "g");

const parts = (s) => {
  const m = /^(\$?)([A-Za-z]+)(\$?)(\d+)$/.exec(s);
  if (m[2].length > 3 || m[4] === "0" || m[4][0] === "0") return null;
  return { cd: m[1], col: colIndex(m[2]), rd: m[3], row: Number(m[4]) - 1 };
};
const fmt = (p) => `${p.cd}${colName(p.col)}${p.rd}${p.row + 1}`;

// op: { axis: "row" | "col", at: 0-based index, n, del }
const point = (v, { at, n, del }) => {
  if (!del) return v >= at ? v + n : v;
  if (v < at) return v;
  return v < at + n ? null : v - n;
};
const span = (lo, hi, { at, n, del }) => {
  if (!del) return [lo >= at ? lo + n : lo, hi >= at ? hi + n : hi];
  if (lo >= at && hi < at + n) return null;
  const f = (v, end) => (v < at ? v : v >= at + n ? v - n : end ? at - 1 : at);
  return [f(lo, false), f(hi, true)];
};

function rewrite(text, op) {
  const k = op.axis;
