    let out = "";
    for (const seg of s.split(/("(?:[^"]|"")*"?)/)) {
      if (seg.startsWith('"')) { out += seg; continue; }
      out += seg.replace(RE, (all, a, b) => {
        const p = parseParts(a), q = b && parseParts(b);
        if (!p || (b && !q)) return all;
        if (!b) {
          const v = point(p[k], op);
          return v == null ? "#REF!" : fmt({ ...p, [k]: v });
        }
        const flip = p[k] > q[k];
        const r = span(flip ? q[k] : p[k], flip ? p[k] : q[k], op);
        if (!r) return "#REF!";
        return `${fmt({ ...p, [k]: flip ? r[1] : r[0] })}:${fmt({ ...q, [k]: flip ? r[0] : r[1] })}`;
