export function toCSV(sheet, values = null) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) { const p = parseAddr(a); rows = Math.max(rows, p.row + 1); cols = Math.max(cols, p.col + 1); }
