    const fields = [];
    for (let c = 0; c < cols; c++) {
      const a = toAddr(c, r);
      fields.push(quote(values ? text(values.get(a)) : sheet.cells.get(a) ?? ""));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detect(src) {
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (const ch of src) {
    if (ch === '"') inQ = !inQ;
    else if (!inQ) { if (ch === "\n" || ch === "\r") break; if (ch in counts) counts[ch]++; }
  }
  let best = ",";
  for (const d of [";", "\t"]) if (counts[d] > counts[best]) best = d;
  return best;
}

